CREATE TABLE tb_refresh_tokens (id BIGINT GENERATED ALWAYS AS IDENTITY,usuario_id BIGINT NOT NULL,token_hash VARCHAR(64) NOT NULL,expira_em TIMESTAMP(6) NOT NULL,revogado BOOLEAN NOT NULL,criado_em TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT uk_refresh_hash UNIQUE(token_hash),CONSTRAINT fk_refresh_usuario FOREIGN KEY(usuario_id) REFERENCES tb_usuarios(id));
CREATE TABLE tb_password_reset_tokens (id BIGINT GENERATED ALWAYS AS IDENTITY,usuario_id BIGINT NOT NULL,token_hash VARCHAR(64) NOT NULL,expira_em TIMESTAMP(6) NOT NULL,utilizado_em TIMESTAMP(6),criado_em TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT uk_reset_hash UNIQUE(token_hash),CONSTRAINT fk_reset_usuario FOREIGN KEY(usuario_id) REFERENCES tb_usuarios(id));
CREATE INDEX idx_refresh_usuario ON tb_refresh_tokens(usuario_id); CREATE INDEX idx_reset_usuario ON tb_password_reset_tokens(usuario_id);
